    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class Phi
    {
        public static long Run(long n)
        {
            long result = n;
            for (long p = 2; p * p <= n; p++)
            {
                if (n % p == 0)
                {
                    while (n % p == 0) n /= p;
                    result -= result / p;
                }
            }
            if (n > 1) result -= result / n;
            return result;
        }
    }
}

