        public static int Run()
        {
            long t = DateTime.UtcNow.Ticks;
            int hash1 = (int)(((ulong)t >> 32) ^ (ulong)t);
            int hash2 = (int)((long)t ^ ((long)t >> 32));
            int hash3 = _counter++;
            return hash1 ^ hash2 ^ hash3;
        }
    }
